    "text.fast-community-and-developer-support-through-d-aafec6": {
      "en": "Fast community and developer support through discussions and forums.",
      "hu": "Gyors közösségi és fejlesztői segítség beszélgetéseken és fórumokon keresztül.",
      "en-GB": "Fast community and developer support through discussions and forums.",
      "ms": "Sokongan komuniti dan pembangun yang pantas melalui perbincangan dan forum.",
      "ca": "Suport ràpid de la comunitat i dels desenvolupadors mitjançant debats i fòrums.",
      "da": "Hurtig hjælp fra fællesskabet og udvikleren via diskussioner og fora.",
      "de": "Schnelle Hilfe von Community und Entwickler über Diskussionen und Foren.",
      "es": "Ayuda rápida de la comunidad y los desarrolladores mediante debates y foros.",
      "fr": "Aide rapide de la communauté et du développeur via les discussions et les forums.",
      "hr": "Brza pomoć zajednice i razvojnog programera putem rasprava i foruma.",
      "id": "Dukungan komunitas dan pengembang yang cepat melalui diskusi dan forum.",
      "it": "Assistenza rapida dalla community e dallo sviluppatore tramite discussioni e forum.",
      "lv": "Ātrs kopienas un izstrādātāja atbalsts diskusijās un forumos.",
      "nl": "Snelle hulp van de community en ontwikkelaar via discussies en forums.",
      "nb": "Rask hjelp fra fellesskapet og utvikleren via diskusjoner og fora.",
      "pl": "Szybka pomoc społeczności i twórcy w dyskusjach i na forach.",
      "pt-BR": "Suporte rápido da comunidade e do desenvolvedor por discussões e fóruns.",
      "pt-PT": "Apoio rápido da comunidade e do programador através de discussões e fóruns.",
      "ro": "Ajutor rapid din partea comunității și dezvoltatorului prin discuții și forumuri.",
      "sk": "Rýchla pomoc komunity a vývojára prostredníctvom diskusií a fór.",
      "sl": "Hitra pomoč skupnosti in razvijalca prek razprav in forumov.",
      "fi": "Nopeaa yhteisön ja kehittäjän tukea keskusteluissa ja foorumeilla.",
      "sv": "Snabb hjälp från gemenskapen och utvecklaren via diskussioner och forum.",
      "vi": "Hỗ trợ nhanh từ cộng đồng và nhà phát triển qua thảo luận và diễn đàn.",
      "tr": "Tartışmalar ve forumlar üzerinden hızlı topluluk ve geliştirici desteği.",
      "cs": "Rychlá podpora komunity a vývojáře prostřednictvím diskuzí a fór.",
      "el": "Γρήγορη υποστήριξη από την κοινότητα και τον δημιουργό μέσω συζητήσεων και φόρουμ.",
      "bg": "Бърза подкрепа от общността и разработчика чрез дискусии и форуми.",
      "ru": "Быстрая помощь сообщества и разработчика в обсуждениях и на форумах.",
      "uk": "Швидка допомога спільноти й розробника в обговореннях і на форумах.",
      "he": "תמיכה מהירה מהקהילה ומהמפתח דרך דיונים ופורומים.",
      "ar": "دعم سريع من المجتمع والمطوّر عبر المناقشات والمنتديات.",
      "fa": "پشتیبانی سریع انجمن و توسعه‌دهنده از طریق گفت‌وگوها و تالارها.",
      "hi": "चर्चाओं और फ़ोरम से समुदाय और डेवलपर की त्वरित सहायता।",
      "th": "การสนับสนุนที่รวดเร็วจากชุมชนและผู้พัฒนาผ่านการสนทนาและฟอรัม",
      "ja": "ディスカッションやフォーラムを通じた、コミュニティと開発者による迅速なサポート。",
      "zh-Hans": "通过讨论和论坛获得社区与开发者的快速支持。",
      "zh-Hant": "透過討論及論壇取得社群與開發者的快速支援。",
      "ko": "토론과 포럼을 통한 커뮤니티 및 개발자의 빠른 지원."
    },
